import("stdfaust.lib");
MAXD = 96000;
dtime = hslider("Delay Time [unit:ms]", 250, 10, 1000, 1) : si.smoo
        : *(ma.SR/1000.0) : min(MAXD-1) : max(1);
fb = hslider("Feedback", 0.4, 0, 0.95, 0.01) : si.smoo;
mix = hslider("Dry/Wet", 0.5, 0, 1, 0.01) : si.smoo;
process = outL, outR with {
    cross(fbL, fbR, inL, inR) = inL + fbR*fb, inR + fbL*fb;
    wet = cross ~ (de.fdelay(MAXD, dtime), de.fdelay(MAXD, dtime));
    outL = _.0*(1-mix) + wet.0*mix;
    outR = _.1*(1-mix) + wet.1*mix;
};

