import("stdfaust.lib");
threshold = hslider("Threshold [unit:dB]", -40, -80, 0, 0.1) : si.smoo;
ratio = hslider("Ratio", 2.0, 1.0, 10.0, 0.01) : si.smoo;
attack = hslider("Attack [unit:ms]", 10, 0.1, 200, 0.1) : si.smoo;
release = hslider("Release [unit:ms]", 100, 1, 500, 0.1) : si.smoo;
attS = attack * ma.SR/1000.0;
relS = release * ma.SR/1000.0;
expander(x) = x * (ba.db2linear(max(0, (threshold - ba.linear2db(env(x)+1e-12)) * (ratio - 1)))) with {
