import("stdfaust.lib");
ratio = hslider("Ratio", 4, 1, 20, 0.1) : si.smoo;
thresh = hslider("Threshold [unit:dB]", -20, -60, 0, 0.1) : ba.db2linear : si.smoo;
att = hslider("Attack [unit:s]", 0.01, 0.001, 0.5, 0.001) : si.smoo;
rel = hslider("Release [unit:s]", 0.1, 0.001, 1, 0.001) : si.smoo;
sidechain_compressor(L,R,SC) = (L*gain_s, R*gain_s) with {
    env = SC : an.amp_follower_ar(att, rel);
    gain = (env > thresh) ? ((thresh + (env - thresh)/ratio)/env) : 1;
    gain_s = gain : si.smoo;
};
process = sidechain_compressor;

